package ca.shivam.university;

/** Dependency-free standalone HTML portfolio report. */
public final class UniversityReport {
    private UniversityReport() {}

    public static String render(UniversityService service, EnrollmentAnalytics.Portfolio analytics, DataQualityAuditor.Report quality, DegreeAuditEngine.AuditResult audit) {
        StringBuilder bottlenecks = new StringBuilder();
        for (EnrollmentAnalytics.CourseDemand item : analytics.bottlenecks()) {
            bottlenecks.append("<tr><td>").append(escape(item.course().code())).append("</td><td>").append(escape(item.course().title())).append("</td><td>").append(item.enrolled()).append("/").append(item.course().capacity()).append("</td><td>").append(item.waitlisted()).append("</td><td><span class=\"pill ").append(escape(item.pressureBand())).append("\">").append(escape(item.pressureBand())).append("</span></td></tr>");
        }
        if (bottlenecks.length() == 0) bottlenecks.append("<tr><td colspan=\"5\">No current capacity bottlenecks.</td></tr>");
        StringBuilder groups = new StringBuilder();
        if (audit != null) for (DegreeAuditEngine.GroupProgress group : audit.groups()) {
            double width = group.requiredCredits() <= 0.0 ? (group.satisfied() ? 100.0 : 0.0) : Math.min(100.0, group.earnedCredits() / group.requiredCredits() * 100.0);
            groups.append("<div class=\"group\"><div><strong>").append(escape(group.name())).append("</strong><span>").append(group.satisfied() ? "complete" : "in progress").append("</span></div><div class=\"bar\"><i style=\"width:").append(width).append("%\"></i></div><small>").append(group.earnedCredits()).append(" earned · ").append(group.inProgressCredits()).append(" in progress</small></div>");
        }
        String auditCard = audit == null ? "" : "<section class=\"panel\"><h2>Degree audit</h2><div class=\"audit-head\"><div><strong>" + escape(audit.student().name()) + "</strong><span>" + escape(audit.program().name()) + "</span></div><b>" + String.format(java.util.Locale.ROOT, "%.1f%%", audit.completionPercent()) + "</b></div><div class=\"bar hero\"><i style=\"width:" + audit.completionPercent() + "%\"></i></div><p>" + audit.earnedCredits() + " earned credits · " + audit.inProgressCredits() + " in progress · GPA " + audit.gpa() + " · standing signal " + escape(audit.standing().name()) + "</p>" + groups + "</section>";
        return "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>University Management System · Portfolio Report</title><style>:root{color-scheme:dark;--bg:#07111f;--panel:#0d1b2e;--line:#213552;--text:#e8f0fb;--muted:#9fb0c6;--accent:#60a5fa;--accent2:#8b5cf6}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 0,#132f55,transparent 35%),var(--bg);font:15px Inter,system-ui,sans-serif;color:var(--text)}main{max-width:1100px;margin:auto;padding:48px 24px}.eyebrow{color:#93c5fd;text-transform:uppercase;letter-spacing:.16em;font-size:12px}h1{font-size:clamp(34px,6vw,64px);margin:8px 0 12px}h1 span{background:linear-gradient(90deg,var(--accent),#c4b5fd);-webkit-background-clip:text;color:transparent}p{color:var(--muted);line-height:1.65}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:30px 0}.card,.panel{background:linear-gradient(145deg,#10223a,#0b1728);border:1px solid var(--line);border-radius:18px;padding:20px;box-shadow:0 18px 45px #0005}.card b{display:block;font-size:30px}.card span,.audit-head span{color:var(--muted)}.panel{margin:16px 0}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}th{color:#a5b4fc}.pill{padding:4px 8px;border-radius:999px;background:#1e293b}.pill.critical{background:#7f1d1d}.pill.high{background:#78350f}.pill.moderate{background:#164e63}.bar{height:8px;background:#17263b;border-radius:999px;overflow:hidden;margin:9px 0}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),var(--accent2))}.hero{height:12px}.group{margin:16px 0}.group>div:first-child,.audit-head{display:flex;justify-content:space-between;gap:16px}.audit-head b{font-size:28px}footer{color:#72839a;text-align:center;margin-top:30px}@media(max-width:760px){.grid{grid-template-columns:repeat(2,1fr)}table{font-size:12px}}</style></head><body><main><div class=\"eyebrow\">Engineering portfolio · Java 17</div><h1>University <span>Management System</span></h1><p>Generated from the same domain model used by enrollment, waitlists, transcripts, degree audits and capacity analytics. No JavaScript or external runtime dependencies.</p><div class=\"grid\"><div class=\"card\"><b>" + service.students().size() + "</b><span>students</span></div><div class=\"card\"><b>" + service.courses().size() + "</b><span>courses</span></div><div class=\"card\"><b>" + analytics.totalActiveSeats() + "</b><span>active seats</span></div><div class=\"card\"><b>" + analytics.totalWaitlisted() + "</b><span>waitlisted</span></div></div>" + auditCard + "<section class=\"panel\"><h2>Capacity intelligence</h2><p>Average active-seat fill rate: " + String.format(java.util.Locale.ROOT, "%.1f%%", analytics.averageFillRate() * 100.0) + "</p><table><thead><tr><th>Course</th><th>Title</th><th>Seats</th><th>Waitlist</th><th>Pressure</th></tr></thead><tbody>" + bottlenecks + "</tbody></table></section><section class=\"panel\"><h2>Data quality</h2><p>" + (quality.healthy() ? "Healthy" : "Review required") + " · " + quality.errors() + " errors · " + quality.warnings() + " warnings</p></section><footer>Generated by University Management System v3 · portfolio prototype</footer></main></body></html>";
    }

    private static String escape(String value) { if (value == null) return ""; return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&#39;"); }
}
